#include <cstddef>
#include <cstdint>
#include <vector>

bool looksLikePrologue(const std::vector<std::uint8_t>& code, std::size_t at)
{
    const std::size_t left{ at < code.size() ? code.size() - at : 0 };
    const auto b = [&](std::size_t i) { return code[at + i]; };
    if (left >= 1 && (b(0) == 0x55 || b(0) == 0x53 || b(0) == 0x56 || b(0) == 0x57)) return true;
    if (left >= 2 && b(0) == 0x40 && (b(1) == 0x53 || b(1) == 0x55 || b(1) == 0x56 || b(1) == 0x57)) return true;
    if (left >= 2 && b(0) == 0x41 && b(1) >= 0x54 && b(1) <= 0x57) return true;
    if (left >= 4 && b(0) == 0x48 && b(1) == 0x83 && b(2) == 0xEC) return true;
    if (left >= 7 && b(0) == 0x48 && b(1) == 0x81 && b(2) == 0xEC) return true;
    if (left >= 5 && (b(0) == 0x48 || b(0) == 0x4C) && b(1) == 0x89 && (b(2) & 0xC7) == 0x44 && b(3) == 0x24) return true;
    return false;
}

std::vector<std::size_t> findFunctions(const std::vector<std::uint8_t>& code)
{
    std::vector<std::size_t> starts;
    for (std::size_t i{ 0 }; i < code.size(); ++i)
    {
        const bool candidate{ i == 0 || (code[i] != 0xCC && code[i - 1] == 0xCC) };
        if (candidate && looksLikePrologue(code, i)) starts.push_back(i);
    }
    return starts;
}

