using Bytes = std::vector<std::uint8_t>;
static void add(Bytes& b, std::initializer_list<int> more) { for (int x : more) b.push_back(static_cast<std::uint8_t>(x)); }

TEST("prologue patterns") {
    CHECK(looksLikePrologue({ 0x40, 0x53, 0x48, 0x83, 0xEC, 0x20 }, 0));
    CHECK(looksLikePrologue({ 0x48, 0x89, 0x5C, 0x24, 0x08 }, 0));
    CHECK(looksLikePrologue({ 0x4C, 0x89, 0x44, 0x24, 0x18 }, 0));
    CHECK(looksLikePrologue({ 0x48, 0x83, 0xEC, 0x28 }, 0));
    CHECK(looksLikePrologue({ 0x48, 0x81, 0xEC, 0x50, 0x01, 0x00, 0x00 }, 0));
    CHECK(looksLikePrologue({ 0x41, 0x57 }, 0));
    CHECK(looksLikePrologue({ 0x55 }, 0));
}
TEST("not prologues") {
    CHECK(!looksLikePrologue({ 0x48, 0x8B, 0xC1, 0xC3 }, 0));
    CHECK(!looksLikePrologue({ 0x48, 0x89, 0xC8 }, 0));
    CHECK(!looksLikePrologue({ 0x48, 0x83, 0xEC }, 0));
    CHECK(!looksLikePrologue({ 0x48, 0x81, 0xEC, 0x00 }, 0));
    CHECK(!looksLikePrologue({ 0x41, 0x50 }, 0));
    CHECK(!looksLikePrologue({ 0x55 }, 1));
}
TEST("functions between int3 padding") {
    Bytes code;
    add(code, { 0x48, 0x83, 0xEC, 0x28, 0xE8, 0x00, 0x00, 0x00, 0x00, 0x48, 0x83, 0xC4, 0x28, 0xC3 });  // 0
    add(code, { 0xCC, 0xCC });
    add(code, { 0x40, 0x53, 0x48, 0x83, 0xEC, 0x20, 0x5B, 0xC3 });                                       // 16
    add(code, { 0xCC, 0xCC, 0xCC, 0xCC, 0xCC, 0xCC, 0xCC, 0xCC });
    add(code, { 0x8D, 0x04, 0x51, 0xC3 });                                                                // 32: a leaf, no prologue
    add(code, { 0xCC, 0xCC, 0xCC, 0xCC });
    add(code, { 0x48, 0x89, 0x5C, 0x24, 0x08, 0x57, 0x48, 0x83, 0xEC, 0x20 });                           // 40
    CHECK_EQ(findFunctions(code), (std::vector<std::size_t>{ 0, 16, 40 }));
}
TEST("CC inside an instruction is not padding") {
    Bytes code;
    add(code, { 0x55, 0xB8, 0xCC, 0x55, 0x00, 0x00, 0xC3 });
    CHECK_EQ(findFunctions(code), (std::vector<std::size_t>{ 0, 3 }));
    CHECK(findFunctions({}).empty());
    CHECK(findFunctions({ 0x90, 0xC3 }).empty());
}

